public with sharing class AuraWidgetController {
  @AuraEnabled(cacheable=true)
  public static String getWidget(String recordId) {
    return 'widget:' + recordId;
  }

  @AuraEnabled
  public static String saveWidget(String recordId) {
    return 'saved:' + recordId;
  }
}

@IsTest
private class UIAuraComponentsLocalTest {
  @IsTest static void auraEnabledControllerMethodsRun() {
    System.assertEquals('widget:001000000000001AAA', AuraWidgetController.getWidget('001000000000001AAA'));
    System.assertEquals('saved:001000000000001AAA', AuraWidgetController.saveWidget('001000000000001AAA'));
  }

  @IsTest static void auraHandledExceptionHasLocalShape() {
    AuraHandledException blocked = new AuraHandledException('blocked');
    System.assertEquals('System.AuraHandledException', blocked.getTypeName());
    System.assertEquals('blocked', blocked.getMessage());
  }
}

({
  load: function(component) {
    component.get("c.getWidget");
  },
  saveWidget: function(component) {
    component.get("c.saveWidget");
  }
})
